repo.parcels.py:
"""Parcel records."""


class Parcel:
    def __init__(self, depot, grams):
        self.depot = depot
        self.grams = grams

    def __repr__(self):
        return "Parcel(%r, %r)" % (self.depot, self.grams)


ROWS = [('york', 44), ('leeds', 42), ('bath', 45), ('hull', 22), ('leeds', 20), ('york', 54)]


def load_parcels():
    """Yield the stored parcels one at a time."""
    for depot, grams in ROWS:
        yield Parcel(depot, grams)

repo.labels.py:
"""Labels for parcels."""


def label_parcels(names, parcels):
    """Return (lookup, lines): a name -> grams dict and one 'name: grams' line per parcel."""
    pairs = zip(names, (x.grams for x in parcels))
    lookup = dict(pairs)
    lines = ["%s: %s" % (name, value) for name, value in pairs]
    return lookup, lines


def name_list(names):
    """Return the names joined by commas."""
    return ", ".join(names)

